"""Offline workbench for contract-validated result-only documents."""

TEMPLATE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:; font-src 'none'; connect-src 'none'; form-action 'none'; base-uri 'none'">
<title>AIQE · Quality Workbench</title>
<style>
:root{--bg:#f3f5f9;--panel:#fff;--ink:#17253d;--muted:#52627a;--line:#dce3ee;--accent:#244db9;--tint:#edf2ff;--ok:#196748;--okbg:#edf9f2;--bad:#a52d31;--badbg:#fff0f0;--warn:#87540b;--warnbg:#fff6e5;--radius:12px}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit}button,select,summary{cursor:pointer}a{color:var(--accent)}button,input,select{min-height:44px}button{transition:background .15s,border-color .15s}button:hover{background:var(--tint)}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}h1,h2,h3,p{margin:0}h1{font-size:30px;line-height:1.2;letter-spacing:-.8px}h2{font-size:20px;letter-spacing:-.3px}h3{font-size:16px}code,.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.muted{color:var(--muted)}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:1.8px;font-weight:750}.skip{position:absolute;left:16px;top:-100px;background:var(--panel);padding:12px;z-index:4}.skip:focus{top:10px}
header{background:#12213b;color:white;padding:19px 32px;display:flex;align-items:center;gap:20px}.brand{font-size:20px;font-weight:750;letter-spacing:2px}.header-rule{height:24px;width:1px;background:#536079}.header-title{font-size:13px;color:#d4def1}.offline{margin-left:auto;border:1px solid #52617c;border-radius:30px;padding:5px 12px;font-size:12px;color:#e0e7f4}.container{max-width:1536px;margin:auto;padding:28px 32px 64px}.hero{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;margin:0 0 24px}.hero .eyebrow{color:var(--accent);margin-bottom:9px}.hero p{margin-top:11px;color:var(--muted);max-width:650px}.stamp{text-align:right;font-size:12px;color:var(--muted)}.source-strip{border:1px solid #bccced;background:var(--tint);border-radius:var(--radius);padding:12px 16px;margin-bottom:20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:13px}.source-strip strong{color:#183887}.source-strip .disclaimer{margin-left:auto}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:24px}.metric{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:16px 18px}.metric b{font-size:30px;line-height:1.3;display:block;font-variant-numeric:tabular-nums}.metric span{font-size:12px;color:var(--muted)}.metric .metric-label{display:block;color:var(--ink);font-size:13px;margin-bottom:5px}.layout{display:grid;grid-template-columns:350px minmax(0,1fr);gap:22px;align-items:start}.queue,.detail,.errors{border:1px solid var(--line);background:var(--panel);border-radius:var(--radius)}.queue-head{padding:20px 18px 12px}.queue-head h2{font-size:17px}.filter-grid{padding:0 18px 16px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.filter-grid label{font-size:12px;color:var(--muted)}.filter-grid label:first-child{grid-column:1/-1}.filter-grid input,.filter-grid select{display:block;width:100%;margin-top:4px;border:1px solid #a8b7cc;background:var(--panel);color:var(--ink);border-radius:7px;padding:8px;font-size:13px}.queue-count{font-size:12px;color:var(--muted);padding:0 18px 10px}.queue-list{padding:0 8px 8px;max-height:790px;overflow-y:auto}.work-row{display:block;width:100%;text-align:left;border:1px solid transparent;background:white;border-radius:8px;padding:13px 11px;margin:0 0 5px;color:var(--ink)}.work-row[aria-pressed=true]{background:var(--tint);border-color:#9eb4e9;box-shadow:inset 3px 0 var(--accent)}.row-top{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}.row-top b{font-size:13px;overflow-wrap:anywhere}.work-row p{font-size:12px;color:var(--muted);margin-top:5px}.row-meta{display:flex;gap:7px;margin-top:9px;flex-wrap:wrap}.badge{display:inline-block;font-size:11px;line-height:1.6;border:1px solid var(--line);border-radius:5px;padding:2px 7px;font-weight:650;white-space:normal;overflow-wrap:anywhere;color:var(--muted);background:#f5f7fa}.badge.ok{color:var(--ok);background:var(--okbg);border-color:#a5d4b8}.badge.bad{color:var(--bad);background:var(--badbg);border-color:#e5b4b6}.badge.warn{color:var(--warn);background:var(--warnbg);border-color:#e4ca96}.detail{overflow:hidden}.detail-head{padding:24px 26px;background:linear-gradient(110deg,#fafbff,#f0f4fd);border-bottom:1px solid var(--line)}.detail-title{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.detail-title h2{font-size:24px;overflow-wrap:anywhere}.scope{font-size:15px;max-width:760px;margin:12px 0;color:#364862;overflow-wrap:anywhere}.detail-meta{display:flex;gap:10px;flex-wrap:wrap;align-items:center;font-size:12px;color:var(--muted)}.decision{margin:16px 0 0;padding:11px 14px;background:white;border:1px solid var(--line);border-left:3px solid var(--accent);border-radius:6px;font-size:13px}.section{padding:23px 26px;border-bottom:1px solid var(--line)}.section:last-child{border:0}.section-top{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:8px}.section-top h3{font-size:16px}.section-top h3 span{font-size:11px;font-weight:750;letter-spacing:1px;color:var(--accent);margin-right:9px}.section .help{font-size:12px;color:var(--muted);margin-bottom:15px}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.fact{padding:11px 12px;border:1px solid var(--line);border-radius:7px;min-width:0}.fact-label{font-size:11px;color:var(--muted);display:block;margin-bottom:5px}.fact strong{font-size:14px;overflow-wrap:anywhere}.hash{font-size:11px;color:var(--muted);margin-top:14px;overflow-wrap:anywhere}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:11px 12px;vertical-align:top}th{font-size:11px;font-weight:700;color:var(--muted);background:#f8faff}th[scope=row]{background:transparent;font-size:13px;color:var(--ink)}tr:last-child td,tr:last-child th{border-bottom:0}.matrix{border:1px solid var(--line);border-radius:8px;overflow:hidden}.matrix td p{font-size:11px;color:var(--muted);margin-top:4px}.findings{margin-top:12px;font-size:13px;color:var(--bad)}.effort-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:13px}.effort-stats div{background:#f7f9fc;border-radius:7px;padding:12px}.effort-stats strong{display:block;font-size:20px}.effort-stats small{font-size:11px;color:var(--muted)}.coverage{height:7px;background:#e5eaf2;border-radius:10px;margin:10px 0 16px;overflow:hidden}.coverage i{display:block;height:100%;background:var(--accent)}details summary{font-size:13px;font-weight:650;min-height:44px;display:flex;align-items:center;gap:8px}details summary:before{content:'+';font:20px monospace;color:var(--accent)}details[open] summary:before{content:'−'}.binding{font-size:11px}.errors{margin-top:22px;padding:20px}.errors h2{font-size:17px;margin-bottom:8px}.errors summary{color:var(--bad)}.empty{padding:40px 24px;text-align:center;color:var(--muted)}.empty strong{display:block;color:var(--ink);margin-bottom:8px}footer{font-size:12px;color:var(--muted);margin-top:23px}.howto{margin-top:16px;padding:16px;background:var(--tint);border-radius:8px;font-size:13px}.howto code{display:block;margin-top:8px;font-size:12px} .hidden{display:none}
@media(max-width:1050px){.layout{grid-template-columns:295px minmax(0,1fr)}.container{padding:24px 20px}.facts{grid-template-columns:1fr}.source-strip .disclaimer{margin-left:0}.detail-head,.section{padding:20px}.stamp{display:none}}
@media(max-width:760px){header{padding:16px 20px}.header-rule,.header-title{display:none}.container{padding:22px 14px}.hero{display:block}h1{font-size:28px}.metrics{grid-template-columns:1fr 1fr;gap:9px}.metric{padding:13px}.metric b{font-size:25px}.layout{grid-template-columns:1fr}.queue-list{max-height:300px}.filter-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.filter-grid label:first-child{grid-column:1/-1}.detail-title{flex-direction:column}.effort-stats{gap:6px}.effort-stats strong{font-size:17px}.section,.detail-head{padding:18px 15px}.table-wrap{max-width:100%}.source-strip{align-items:flex-start}.offline{font-size:11px}.matrix th,.matrix td{padding:10px 7px}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
</style></head>
<body>
<a class="skip" href="#main">Skip to workbench</a>
<header><div class="brand">AIQE<span style="color:#8daaf3">.</span></div><div class="header-rule"></div><div class="header-title">QUALITY ENGINEERING / WORKBENCH</div><div class="offline">Local snapshot · offline</div></header>
<main class="container" id="main">
<div class="hero"><div><p class="eyebrow">Evidence before acceptance</p><h1>Quality Workbench</h1><p>Review a work item from its frozen scope to acceptance. See what was checked, what changed, and what remains unknown.</p></div><div class="stamp" id="stamp"></div></div>
<div class="source-strip" id="source-strip"></div>
<div class="metrics" id="metrics"></div>
<div class="layout"><aside class="queue" aria-label="Work item queue"><div class="queue-head"><h2>Work items</h2></div>
<div class="filter-grid"><label>Search work ID, run or scope<input id="search" type="search" placeholder="Find a work item…"></label><label>Status<select id="status"><option value="all">All statuses</option><option value="accepted">Accepted</option><option value="pending_review">Pending review</option><option value="rejected">Rejected</option><option value="reopened">Reopened</option></select></label><label>Source<select id="source"><option value="all">All sources</option><option value="synthetic">Synthetic</option><option value="local_test">Local test</option></select></label><label>Evidence<select id="freshness"><option value="all">All versions</option><option value="stale">Stale</option><option value="current">Current</option></select></label></div>
<p class="queue-count" id="queue-count" role="status" aria-live="polite"></p><div class="queue-list" id="queue-list"></div></aside>
<article class="detail" id="detail" aria-label="Selected work item"></article></div>
<section class="errors" id="errors"></section>
<details class="howto"><summary>Use your own validated workbench documents</summary><p>Generate this page from explicit result-only workbench JSON files. Each file is checked against the existing contract; rejected files appear below. Supported labels are synthetic/public_synthetic and local_test/internal. Source labels are declared metadata, not authentication.</p><code>PYTHONPATH=src python3 -m AIQE.dashboard --workbench /path/to/documents --out /private/tmp/aiqe-workbench/index.html</code><p style="margin-top:10px">Native result files require the existing approved adapter before use. This page performs no model calls and exports no raw prompts or responses.</p></details>
<footer id="footer"></footer>
</main>
<script type="application/json" id="aiqe-data">__AIQE_DATA__</script>
<script>
(function(){'use strict';
var DATA=JSON.parse(document.getElementById('aiqe-data').textContent), WB=DATA.workbench, ITEMS=WB.items, selected=0;
var LABELS={accepted:'Accepted',pending_review:'Pending review',rejected:'Rejected',reopened:'Reopened',passed:'Passed',failed:'Failed',unknown:'Unknown',pending:'Pending',preserved:'Preserved',regression:'Regression',error:'Error',skipped:'Skipped',synthetic:'Synthetic',local_test:'Local test',measured:'Claimed measured',self_reported:'Self-reported',missing:'Missing',not_applicable:'Not applicable'};
function el(id){return document.getElementById(id)}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function label(s){return LABELS[s]||s}
function badge(s,tone){var kind=tone===undefined?(['accepted','passed','preserved'].indexOf(s)>=0?'ok':['failed','rejected','regression','error'].indexOf(s)>=0?'bad':'warn'):tone;return '<span class="badge '+esc(kind)+'">'+esc(label(s))+'</span>'}
function minutes(v){return v===null?'N/A':esc(v)+' min'}
function fact(name,value){return '<div class="fact"><span class="fact-label">'+esc(name)+'</span><strong>'+value+'</strong></div>'}
function count(test){return ITEMS.filter(function(i){return test(i.facts)}).length}
function metric(name,value,note){return '<div class="metric"><span class="metric-label">'+esc(name)+'</span><b>'+value+'</b><span>'+esc(note)+'</span></div>'}
var sources=Array.from(new Set(ITEMS.map(function(i){return i.facts.source_type+' / '+i.facts.data_classification}))).join(' · ');
el('stamp').textContent='Generated '+DATA.generated_at;
el('source-strip').innerHTML='<strong>'+esc(sources||'No validated documents')+'</strong><span class="disclaimer">'+(ITEMS.length&&ITEMS.every(function(i){return i.facts.source_type==='synthetic'})?'Synthetic demonstration · no real customer results':'Declared source metadata · verify provenance before use')+'</span>';
el('metrics').innerHTML=metric('Validated work items',ITEMS.length,'Contract consistency checked')+metric('Accepted',count(function(f){return f.status==='accepted'}),'Q5 + Q6 + review + current versions')+metric('Needs a decision',count(function(f){return f.status!=='accepted'}),'Pending, rejected or reopened')+metric('Stale evidence',count(function(f){return f.stale}),'Frozen and observed versions differ');
el('footer').textContent=DATA.dashboard_version+' · Result-only snapshot · Contract validation does not authenticate digests or source labels. No network connections.';
function renderQueue(){var query=el('search').value.toLowerCase().trim(),status=el('status').value,source=el('source').value,fresh=el('freshness').value;
var visible=[];ITEMS.forEach(function(item,index){var f=item.facts,text=(f.work_item_id+' '+f.run_id+' '+item.document.work_item.frozen_scope).toLowerCase();if((!query||text.indexOf(query)>=0)&&(status==='all'||f.status===status)&&(source==='all'||f.source_type===source)&&(fresh==='all'||f.stale===(fresh==='stale')))visible.push(index)});
if(visible.indexOf(selected)<0)selected=visible.length?visible[0]:-1;
el('queue-count').textContent=visible.length+' of '+ITEMS.length+' work items';
el('queue-list').innerHTML=visible.length?visible.map(function(index){var i=ITEMS[index],f=i.facts;return '<button type="button" class="work-row" data-index="'+index+'" aria-pressed="'+(index===selected)+'" aria-controls="detail"><span class="row-top"><b class="mono">'+esc(f.work_item_id)+'</b>'+badge(f.status)+'</span><p>'+esc(i.document.work_item.frozen_scope)+'</p><span class="row-meta">'+badge(f.source_type,'')+(f.stale?badge('Stale versions','warn'):'')+'</span></button>'}).join(''):'<div class="empty"><strong>No matching work items</strong>Change the search or filters to broaden the queue.</div>';
Array.prototype.forEach.call(el('queue-list').querySelectorAll('button'),function(b){b.addEventListener('click',function(){selected=Number(b.dataset.index);Array.prototype.forEach.call(el('queue-list').querySelectorAll('button'),function(other){other.setAttribute('aria-pressed',other===b?'true':'false')});renderDetail()})});renderDetail()}
function renderDetail(){if(selected<0||!ITEMS.length){el('detail').innerHTML='<div class="empty"><strong>'+(ITEMS.length?'No item selected':'Add workbench documents to begin')+'</strong>'+(ITEMS.length?'The selected filters have no matching evidence.':'Use --workbench with validated result-only JSON. Rejected documents remain visible below.')+'</div>';return}
var i=ITEMS[selected],d=i.document,f=i.facts,w=d.work_item,e=f.effort,t=f.effort_trust,q=d.q6;
var reasons=[];if(f.stale)reasons.push('Version mismatch: acceptance requires fresh evidence.');if(f.validation_result==='unknown')reasons.push('Independent validation is unknown.');if(f.validation_result==='failed')reasons.push('Independent validation failed.');if(f.q6_status==='unknown')reasons.push('Q6 detection preservation is unknown.');if(f.q6_status==='regression')reasons.push('Q6 found a detection or correctness regression.');if(w.review.state!=='accepted')reasons.push('Human review: '+label(w.review.state).toLowerCase()+'.');
var html='<div class="detail-head"><div class="detail-title"><div><p class="eyebrow muted">WORK ITEM / '+esc(f.run_id)+'</p><h2 class="mono">'+esc(f.work_item_id)+'</h2></div>'+badge(f.status)+'</div><p class="scope">'+esc(w.frozen_scope)+'</p><div class="detail-meta">'+badge(f.source_type,'')+'<span>'+esc(f.data_classification)+'</span>'+badge(f.stale?'Stale versions':'Current versions',f.stale?'warn':'ok')+'</div><div class="decision">'+esc(reasons.length?reasons.join(' '):'Recorded acceptance conditions are satisfied for this frozen version set. Evidence authenticity still requires verification.')+'</div></div>';
html+='<section class="section"><div class="section-top"><h3><span>Q5</span>Acceptance evidence</h3>'+badge(f.validation_result)+'</div><p class="help">A completion claim is separate from independent validation and human review.</p><div class="facts">'+fact('Completion claim',w.claimed_complete?'Claimed complete':'Not claimed complete')+fact('Independent validation',badge(f.validation_result))+fact('Human review',badge(w.review.state)+'<div class="muted" style="font-size:12px;margin-top:5px">'+esc(w.review.actor||'No reviewer recorded')+'</div>')+'</div><p class="hash">Validation evidence SHA-256<br><code>'+esc(w.validation.evidence_sha256||'N/A · no independent evidence recorded')+'</code></p></section>';
html+='<section class="section"><div class="section-top"><h3><span>Q6</span>Detection preservation</h3>'+badge(f.q6_status)+'</div><p class="help">Known-defect implementations should fail. Correct implementations should pass. These are supplied observations; this document contains no runner logs.</p><div class="matrix table-wrap"><table><thead><tr><th scope="col">Implementation</th><th scope="col">Before tests</th><th scope="col">After tests</th></tr></thead><tbody>';
['correct','defective'].forEach(function(kind){html+='<tr><th scope="row">'+(kind==='correct'?'Correct':'Known defect')+'</th>';['before','after'].forEach(function(phase){var value=q?q[phase+'_'+kind]:'unknown';var tone=value==='unknown'||value==='skipped'?'warn':(value===(kind==='correct'?'passed':'failed')?'ok':'bad');html+='<td>'+badge(value,tone)+'<p>Expected '+(kind==='correct'?'pass':'failure')+'</p></td>'});html+='</tr>'});html+='</tbody></table></div><p class="hash">Challenge: '+esc(q?q.challenge_id:'N/A · no challenge recorded')+'</p>';
if(f.q6_findings.length)html+='<p class="findings"><b>Findings:</b> '+esc(f.q6_findings.map(function(v){return v.replace(/_/g,' ')}).join(' · '))+'</p>';
html+='</section><section class="section"><div class="section-top"><h3><span>Q7</span>Human effort coverage</h3>'+badge(t.trust==='unverified'?'Unverified claims':'Not applicable',t.trust==='unverified'?'warn':'')+'</div><p class="help">Category coverage is completeness, not verification. Claimed measurements and self-reports remain unverified; missing minutes are N/A.</p><div class="effort-stats"><div><small>Category coverage</small><strong>'+e.covered_categories+' / '+e.applicable_categories+'</strong></div><div><small>Complete claimed total</small><strong>'+minutes(e.total_minutes)+'</strong></div><div><small>Verified total</small><strong>'+minutes(t.verified_minutes)+'</strong></div></div><div class="coverage" role="img" aria-label="'+e.covered_categories+' of '+e.applicable_categories+' applicable effort categories covered"><i style="width:'+(e.applicable_categories?e.covered_categories/e.applicable_categories*100:0)+'%"></i></div><div class="table-wrap"><table><thead><tr><th scope="col">Category</th><th scope="col">Minutes</th><th scope="col">Recorded source</th></tr></thead><tbody>';
['preparation','review','rework','acceptance','coordination'].forEach(function(key){var entry=d.effort[key];html+='<tr><th scope="row">'+esc(key.charAt(0).toUpperCase()+key.slice(1))+'</th><td>'+minutes(entry.minutes)+'</td><td>'+badge(entry.source,entry.source==='missing'?'warn':'')+'</td></tr>'});html+='</tbody></table></div><p class="hash">Claimed measured: '+minutes(t.claimed_measured_minutes)+' · Self-reported: '+minutes(t.self_reported_minutes)+' · Missing categories: '+t.missing_categories+' · Verified categories: '+t.verified_categories+'</p></section>';
html+='<section class="section"><div class="section-top"><h3>Provenance & version binding</h3>'+badge(f.stale?'Stale':'Current',f.stale?'warn':'ok')+'</div><p class="help">Freshness compares frozen and observed version labels. A matching label or digest does not authenticate the underlying artifact.</p><p class="hash">Input file<br><code>'+esc(i.source_path)+'</code></p><p class="hash">Native report SHA-256<br><code>'+esc(d.provenance.report_sha256)+'</code></p><details><summary>Inspect all 9 version bindings</summary><div class="table-wrap"><table class="binding"><thead><tr><th scope="col">Artifact</th><th scope="col">Frozen</th><th scope="col">Observed</th><th scope="col">Binding</th></tr></thead><tbody>';
Object.keys(d.provenance.frozen_versions).sort().forEach(function(key){var frozen=d.provenance.frozen_versions[key],observed=d.provenance.observed_versions[key];html+='<tr><th scope="row">'+esc(key.replace(/_/g,' '))+'</th><td class="mono">'+esc(frozen)+'</td><td class="mono">'+esc(observed)+'</td><td>'+badge(frozen===observed?'Match':'Changed',frozen===observed?'':'warn')+'</td></tr>'});html+='</tbody></table></div></details></section>';el('detail').innerHTML=html}
if(WB.unreadable.length){el('errors').innerHTML='<details open><summary>'+WB.unreadable.length+' rejected files · excluded from the work queue</summary><div class="table-wrap"><table><thead><tr><th>File</th><th>Reason</th><th>Details</th></tr></thead><tbody>'+WB.unreadable.map(function(f){return '<tr><td class="mono">'+esc(f.source_path)+'</td><td>'+badge(f.reason_code,'bad')+'</td><td>'+esc(f.message)+'</td></tr>'}).join('')+'</tbody></table></div></details>'}else{el('errors').innerHTML='<h2>Import checks</h2><p class="muted">All supplied documents passed contract validation. No rejected files.</p>'}
['search','status','source','freshness'].forEach(function(id){el(id).addEventListener(id==='search'?'input':'change',renderQueue)});renderQueue();
})();
</script></body></html>'''
